    {
      "@id": "activity:translation-story_text_1-2026-07-09T18:46:12.344540+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T18:46:12.344540+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_1",
      "@type": "prov:Entity",
      "prov:value": "Aristotle walked as he taught. He believed the act of moving — through space, through questions, through observation — was itself a form of thinking. Two thousand years later, the research agrees."
    },
    {
      "@id": "entity:target-story_text_1-v1",
      "@type": "prov:Entity",
      "prov:value": "Aristotele camminava mentre insegnava. Credeva che l'atto del muoversi - attraverso lo spazio, attraverso le domande, attraverso l'osservazione - fosse esso stesso un forma di pensiero. Duemila anni dopo, la ricerca concorda.",
      "generated_by": {
        "@id": "activity:translation-story_text_1-2026-07-09T18:46:12.344540+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_1"
      }
    },
    {
      "@id": "activity:translation-story_text_2-2026-07-09T18:46:12.344540+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T18:46:12.344540+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_2",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware puts that insight in your pocket. Teachers design activities that bring curriculum to life in the real world. Students explore, capture, and reflect. Peri guides the inquiry. And learning — finally — moves."
    },
    {
      "@id": "entity:target-story_text_2-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware ti mette quell'istruzione in tasca. Gli insegnanti progettano attività che rendono il programma vivo nel mondo reale. Gli studenti esplorano, catturano e riflettono. Peri guida l'inchiesta. E l'apprendimento - finalmente - si muove.",
      "generated_by": {
        "@id": "activity:translation-story_text_2-2026-07-09T18:46:12.344540+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_2"
      }
    },
