    },
    {
      "@id": "entity:source-meet_peri.step.1.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri sets the scene and asks your child what they notice. No right answer yet — just looking."
    },
    {
      "@id": "entity:target-meet_peri.step.1.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Peri crea l'atmosfera e chiede al tuo bambino cosa notano. Non ci sono ancora risposte giuste - solo l'osservazione.",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.1.desc-2026-07-09T19:05:20.038323+00:00"
      },
      "used_source": {
