    {
      "@id": "activity:translation-field_journal_desc-2026-07-09T19:45:09.211166+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T19:45:09.211166+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-field_journal_desc",
      "@type": "prov:Entity",
      "prov:value": "Students don't just do an activity — they record it. The Field Journal is where raw observations become structured knowledge. Back at their desk, students expand their notes with extended analysis, personal reflection, and connections to what they already know. Teachers can review, respond, and promote entries to the student's permanent portfolio."
    },
    {
      "@id": "entity:target-field_journal_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Gli studenti non si limitano a fare un'attività - la registrano. Il Quaderno dei Campi è il luogo in cui le osservazioni grezze diventano conoscenze strutturate. Tornati alla scrivania, gli studenti espandono i loro appunti con analisi approfondite, riflessioni personali e connessioni con ciò che già sanno. Gli insegnanti possono rivedere, rispondere e promuovere le entrate al portfolio permanente dello studente.",
      "generated_by": {
        "@id": "activity:translation-field_journal_desc-2026-07-09T19:45:09.211166+00:00"
      },
      "used_source": {
        "@id": "entity:source-field_journal_desc"
      }
    },
