    {
      "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-09T19:52:39.505487+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T19:52:39.505487+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr",
      "@type": "prov:Entity",
      "prov:value": "When you upload a PDF or CSV, Ollama extracts the criteria once and caches them. Re-uploading the same file skips Ollama entirely (checksum match). A different file triggers re-extraction. Pre-seeded state sets were hand-authored and are always instant. Sets expire annually — you'll see a warning near the expiry date."
    },
    {
      "@id": "entity:target-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-v1",
      "@type": "prov:Entity",
      "prov:value": "Quando carichi un PDF o CSV, Ollama estrae i criteri una volta e li memorizza in cache. Il caricamento dello stesso file consente di saltare Ollama (marchio di controllo corrispondente). Un file diverso scatena la nuova estrazione. I set di stato preimpostati sono stati scritti manualmente e sono sempre immediati. I set scadono annualmente - vedrai un avviso vicino alla data di scadenza.",
      "generated_by": {
        "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-09T19:52:39.505487+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr"
      }
    },
