    },
    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware ha avuto inizio come un documento bianco scritto all'interno di McGraw-Hill Education. Argomentava che i dispositivi mobili dotati di GPS avrebbero trasformato l'apprendimento - che gli studenti camminando attraverso luoghi reali, guidati da indagini strutturate, potevano imparare in un modo che i libri di testo non permettevano mai.",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-09T19:53:02.216238+00:00"
      },
      "used_source": {
        "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w"
      }
    },
