    {
      "@id": "activity:translation-team_1_bio-2026-07-09T20:00:57.563398+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T20:00:57.563398+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-team_1_bio",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam."
    },
    {
      "@id": "entity:target-team_1_bio-v1",
      "@type": "prov:Entity",
      "prov:value": "Paul ha trascorso un decennio come insegnante, quattro anni lavorando per edtech e da due decenni sta sperimentando come far uscire l'apprendimento dai libri e dalle aule. Peripateticware sfrutta i progressi delle LLMs e utilizza le tecnologie mobili per permettere agli studenti di imparare dal mondo con la guida dei loro insegnanti ovunque decidano di andare.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-07-09T20:00:57.563398+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      }
    },
