      }
    },
    {
      "@id": "entity:source-curriculumImportPage.description",
      "@type": "prov:Entity",
      "prov:value": "Upload a PDF or CSV of official state academic standards (TEKS, NGSS, Common Core, etc.). Ollama extracts each standard for review. Once saved as a global set, all teachers and homeschool parents can map their activities against these standards. Re-uploading the same file skips processing (checksum cache)."
    },
    {
      "@id": "entity:target-curriculumImportPage.description-v1",
      "@type": "prov:Entity",
      "prov:value": "Carica un PDF o CSV degli standard accademici ufficiali dello stato (TEKS, NGSS, Common Core, ecc.). Ollama estrae ogni standard per la revisione. Una volta salvato come set globale, tutti gli insegnanti e i genitori che homeschool possono mappare le loro attività rispetto a questi standard. Il caricamento dello stesso file consente di saltare il processo (cache checksum).",
      "generated_by": {
        "@id": "activity:translation-curriculumImportPage.description-2026-07-09T20:01:19.710076+00:00"
      },
      "used_source": {
        "@id": "entity:source-curriculumImportPage.description"
      }
    },
